import{_ as i,o as n,c as t,a0 as a}from"./chunks/framework.DhQjJcnt.js";const g=JSON.parse('{"title":"Skill: /architecture","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/architecture.md","filePath":"references/skills/architecture.md"}'),c={name:"references/skills/architecture.md"};function o(l,e,r,s,h,u){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="skill-architecture" tabindex="-1">Skill: <code>/architecture</code> <a class="header-anchor" href="#skill-architecture" aria-label="Permalink to &quot;Skill: `/architecture`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>architecture</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/architecture</code></li><li>Đóng vai trò là lệnh <strong>Router (Điều hướng)</strong> tổng phân phối các công việc liên quan đến kiến trúc tới các Skill con tương ứng.</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Member sẽ nhập vào một khu vực kiến trúc (Operational Area), hoặc một Module (CMP ID), hoặc đơn giản là một nhu cầu chung về kiến trúc.</li><li>Agent tự động quét và phân giải (Resolve ID) sử dụng các lệnh nội bộ (<code>flowgrid_docs_route</code>, <code>flowgrid_docs_list_ids</code>).</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Không trực tiếp sửa file, mà sẽ <strong>điều hướng</strong> sang một trong các Skill con chuyên sâu.</li><li>Bảng điều hướng (Route Map): <ul><li>Hỏi về mục đích kinh doanh, chân dung người dùng → Gọi <code>/overview</code>.</li><li>Hỏi về nhóm màn hình (kênh giao tiếp) → Gọi <code>/surfaces</code>.</li><li>Hỏi về Module / Chức năng (CMP) → Gọi <code>/module</code>.</li><li>Hỏi về hạ tầng, vật lý → Gọi <code>/deployment</code>.</li><li>Quyết định kiến trúc → Gọi <code>/decision</code>.</li><li>Các quy trình nghiệp vụ chéo → Gọi <code>/business-process</code>, <code>/db-erd</code>, <code>/cross-service</code>.</li></ul></li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Tách biệt rõ ràng ranh giới giữa <strong>Kiến trúc Kỹ thuật (Technical Architecture)</strong> và <strong>Đặc tả Nghiệp vụ (Business Spec)</strong>.</li><li>Kiến trúc (Architecture) chỉ xoay quanh cấu trúc hệ thống, dịch vụ nội bộ, cronjobs, hạ tầng cơ sở dữ liệu và các luồng kỹ thuật cắt ngang (Cross-cutting flows như Auth).</li><li>Cấm lặp lại chân dung người dùng (Personas) hay use-cases chi tiết trong các file kiến trúc. Thay vào đó, nó phải đề cập thẳng vào thành phần kỹ thuật, Cloud Services và giao tiếp Backend.</li><li>Bắt buộc các sơ đồ thiết kế (Mermaid Flowchart / Sequence Diagram) phải mô hình hóa rõ ràng các luồng ngoại lệ và lỗi (MANDATORY ERROR FLOWS). VD: Redirect khi 401/403 IDOR, hay trạng thái Validation Fail.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li><strong>Điều hướng đến:</strong> Các skill như <code>/overview</code>, <code>/surfaces</code>, <code>/module</code>, <code>/business-process</code>, <code>/db-erd</code>, <code>/deployment</code>.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/architecture</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',18)])])}const p=i(c,[["render",o]]);export{g as __pageData,p as default};
